'use client'
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { form2pdf, form2pdfBlob, form2pdfOpen, form2pdfPrint } from "./lib/form2pdf";
import { faDownload, faPrint } from "@fortawesome/free-solid-svg-icons";
import { BASE_URL } from "./costants";
import type { formTTEC, scheda, SchedaData } from "./lib/type";
import * as dictit from "./ui/it.json";
import * as dicten from "./ui/en.json";
import React, { useEffect, useState } from "react";
import { faArrowRightToFile } from "@fortawesome/free-solid-svg-icons/faArrowRightToFile";


interface Printprops {
    id: string
}

export const DownloadPDFButton: React.FC<Printprops> = ({ id }) => {

    const [formdata, setFormdata] = useState<formTTEC | null>(null);

    const langAttribute = document.getElementsByTagName('html')[0]!.getAttribute('lang');
    const lang: "en" | "it" = langAttribute === 'it' ? 'it' : 'en';
    const dict = lang === 'it' ? dictit : dicten;

    const getAndDownload = async () => {
        if (formdata) {
            const form = await (await fetch(`${BASE_URL}/v1/record/${formdata.scheda_num}`)).json() as SchedaData;
            const slug = lang === 'it' ? formdata.slug_it : formdata.slug_en;
            const pdfBlob = await form2pdfBlob(form, lang, dict, `${BASE_URL}/scheda/${lang}/${slug}`);
            if (!pdfBlob) {
                console.log("error creating pdf");
                return;
            }
            const url = URL.createObjectURL(pdfBlob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `${slug}.pdf`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }
    }

    const openform = async () => {
        const resp = await fetch(`${BASE_URL}/v1/publiccard/${id}`);
        if (resp.status === 200) {
            const form = await resp.json() as formTTEC;
            if (form) {
                const sch = await (await fetch(`${BASE_URL}/v1/record/${form.scheda_num}`)).json() as SchedaData;
                const slug = lang === 'it' ? form.slug_it : form.slug_en;
                await form2pdfOpen(sch, lang, dict, `${BASE_URL}/scheda/${lang}/${slug}`);
            }
        } else {
            console.log("error fetching form data for open cardnumber " + id + " status " + resp.status);
        }
    }

    const printform = async () => {
        const resp = await fetch(`${BASE_URL}/v1/publiccard/${id}`);
        if (resp.status === 200) {
            const form = await resp.json() as formTTEC;
            if (form) {
                const sch = await (await fetch(`${BASE_URL}/v1/record/${form.scheda_num}`)).json() as SchedaData;
                const slug = lang === 'it' ? form.slug_it : form.slug_en;
                await form2pdfPrint(sch, lang, dict, `${BASE_URL}/scheda/${lang}/${slug}`);
            }
        } else {
            console.log("error fetching form data for open cardnumber " + id + " status " + resp.status);
        }
    }

    const askform = async () => {
        const resp = await fetch(`${BASE_URL}/v1/publiccard/${id}`);
        if (resp.status === 200) {
            const form = await resp.json() as formTTEC;
            setFormdata(form);
        } else {
            console.log("error fetching form data for cardnumber " + id + " status " + resp.status);
        }
    }

    useEffect(() => {
        if(formdata!==null) getAndDownload();
    }, [formdata]);

    const dwlpdf = () => {
        if (id !== undefined) {
            askform();
        }
    };

    const openpdf = () => {
        if (id !== undefined) {
            openform();
        }
    };

    const printpdf = () => {
        if (id !== undefined) {
            printform();
        }
    };

    const label = lang === 'it' ? 'Scarica PDF' : 'Download PDF';
    const title = lang === 'it' ? 'scarica' : 'download';
    const label2 = lang === 'it' ? 'Apri PDF' : 'Open PDF';
    const title2 = lang === 'it' ? 'apri' : 'open';
    const label3 = lang === 'it' ? 'Stampa PDF' : 'Print PDF';
    const title3 = lang === 'it' ? 'stampa' : 'print';

    return (
        <div className="flex">
            <button vocab="https://schema.org/" typeof="PrintAction" property="potentialAction" title={title3} aria-label={label3} type="button" onClick={printpdf} className="ml-5 p-2  bg-[#0b4b8a] hover:bg-[#2b6baa] mt-8 text-white rounded-md cursor-pointer">
                {label3}<FontAwesomeIcon icon={faPrint} size='xl' className="fa-fw" />
            </button>
            <button vocab="https://schema.org/" typeof="OpenAction" property="potentialAction" title={title2} aria-label={label2} type="button" onClick={openpdf} className="ml-5 p-2  bg-[#0b4b8a] hover:bg-[#2b6baa] mt-8 text-white rounded-md cursor-pointer">
                {label2}<FontAwesomeIcon icon={faArrowRightToFile} size='xl' className="fa-fw" />
            </button>
            <button vocab="https://schema.org/" typeof="DownloadAction" property="potentialAction" title={title} aria-label={label} type="button" onClick={dwlpdf} className="ml-5 p-2  bg-[#0b4b8a] hover:bg-[#2b6baa] mt-8 text-white rounded-md cursor-pointer">
                {label}<FontAwesomeIcon icon={faDownload} size='xl' className="fa-fw" />
            </button>
        </div>
    )
}